17	void w2jetsq(int i1, int i2, int i3, int i4, int i5, int i6,
18	             FArray2D<std::complex<double>>& za,
19	             FArray2D<std::complex<double>>& zb,
20	             double& msq) {
21	  using namespace constants_mod;
22	  using namespace lc_mod;
23	  using namespace mmsq_cs_mod;
24	  using namespace mxpart_mod;
25	
26	  // Local helicity-amplitude arrays: Fortran dimension (-1:1,-1:1) -> 3x3, start=-1
27	  FArray2D<std::complex<double>> qcd1(3, 3, -1, -1);
28	  FArray2D<std::complex<double>> qcd2(3, 3, -1, -1);
29	  FArray2D<std::complex<double>> qed(3, 3, -1, -1);
30	  double msq1, msq2, msqq;
31	
32	  subqcd(i1, i2, i3, i4, i5, i6, za, zb, qcd1);
33	  subqcd(i1, i2, i3, i4, i6, i5, za, zb, qcd2);
34	
35	  qed(+1,+1) = qcd1(+1,+1) + qcd2(+1,+1);
36	  qed(+1,-1) = qcd1(+1,-1) + qcd2(-1,+1);
37	  qed(-1,+1) = qcd1(-1,+1) + qcd2(+1,-1);
38	  qed(-1,-1) = qcd1(-1,-1) + qcd2(-1,-1);
39	
40	  msq1 = std::norm(qcd1(+1,+1)) + std::norm(qcd1(+1,-1))
41	       + std::norm(qcd1(-1,+1)) + std::norm(qcd1(-1,-1));
42	
43	  msq2 = std::norm(qcd2(+1,+1)) + std::norm(qcd2(+1,-1))
44	       + std::norm(qcd2(-1,+1)) + std::norm(qcd2(-1,-1));
45	
46	  msqq = std::norm(qed(+1,+1)) + std::norm(qed(+1,-1))
47	       + std::norm(qed(-1,+1)) + std::norm(qed(-1,-1));
48	
49	  mmsq_cs(0,+1,+1) = 0.0;
50	  mmsq_cs(1,+1,+1) = 0.0;
51	  mmsq_cs(2,+1,+1) = 0.0;
52	
53	  if ((colourchoice == 1) || (colourchoice == 0)) {
54	    mmsq_cs(1,+1,+1) = msq1;
55	    mmsq_cs(2,+1,+1) = msq2;
56	  }
57	  if ((colourchoice == 2) || (colourchoice == 0)) {
58	    mmsq_cs(0,+1,+1) = -ninth * msqq;
59	  }
60	
61	  msq = mmsq_cs(0,+1,+1) + mmsq_cs(1,+1,+1) + mmsq_cs(2,+1,+1); // @coverage-probe
62	}
63	
64	extern "C" {
65	  void w2jetsq_wrapper(int i1, int i2, int i3, int i4, int i5, int i6,
66	                       std::complex<double>* fza, std::complex<double>* fzb,
67	                       double* fmsq) {
