69	    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
70	    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
71	    w2jetsq(i1, i2, i3, i4, i5, i6, za, zb, *fmsq);
72	  }
