//  SPDX-License-Identifier: GPL-3.0-or-later
//  Copyright (C) 2019-2022, respective authors of MCFM.
//
//  Translated from W2jet/LRcalc.f
//  Computes helicity amplitude building blocks Xpp, Xmp, Xpm, Xmm
//  for the W+2jet process over the two helicity orientations of the
//  gluon pairs (k3,k4) and (k5,k6).

#include "LRcalc.hpp"
#include <complex>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>

void LRcalc(int k1, int k2, int k3, int k4, int k5, int k6,
            FArray2D<std::complex<double>>& za,
            FArray2D<std::complex<double>>& zb,
            FArray1D<std::complex<double>>& A,
            FArray2D<std::complex<double>>& Xpp,
            FArray2D<std::complex<double>>& Xmp,
            FArray2D<std::complex<double>>& Xpm,
            FArray2D<std::complex<double>>& Xmm) {
  using namespace mxpart_mod;
  using namespace sprods_com_mod;

  // Statement functions translated as lambdas
  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) -> std::complex<double> {
    return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
  };
  auto zba2 = [&za, &zb](int i1, int i2, int i3, int i4) -> std::complex<double> {
    return zb(i1,i2)*za(i2,i4) + zb(i1,i3)*za(i3,i4);
  };

  double s12 = s(k1,k2);
  double s34 = s(k3,k4);
  double s56 = s(k5,k6);

  for (int h3 = 1; h3 <= 2; h3++) {
    int l3, l4;
    if (h3 == 1) {
      l3 = k3;
      l4 = k4;
    } else {
      l3 = k4;
      l4 = k3;
    }
    for (int h5 = 1; h5 <= 2; h5++) {
      int l5, l6;
      if (h5 == 1) {
        l5 = k5;
        l6 = k6;
      } else {
        l5 = k6;
        l6 = k5;
      }

      Xmp(h3,h5) = (
          A(2)*s12*za(l3,l5)*zb(l4,l6)*zab2(k1,k3,k4,k2)/zab2(k2,k3,k4,k1)
        - (A(3)+A(4))*za(k1,l3)*za(k1,l5)*zb(k2,l4)*zb(k2,l6)
        + A(5)*zab2(k1,k3,k4,k2)
          *(za(l3,l5)*zb(k2,l4)*zb(l6,k2)/zb(k1,k2)
           +za(k1,l3)*za(k1,l5)*zb(l4,l6)/za(k1,k2))
      ) / s34 / s56 / s12;

      Xpp(h3,h5) = za(l3,l5)/(za(k1,k2)*s12*s34*s56)*(
          (A(3)+A(1))*s12*zb(k1,l6)*zb(l4,k2)
        - (A(4)+A(1))*s12*zb(k2,l6)*zb(l4,k1)
        + A(5)*(zb(k2,l4)*zb(k2,l6)*zab2(k2,k3,k4,k1)
               -zb(k1,l4)*zb(k1,l6)*zab2(k1,k3,k4,k2))
      );

      Xpm(3-h3,3-h5) = (
          A(2)*s12*zb(l3,l5)*za(l4,l6)*zba2(k1,k3,k4,k2)/zba2(k2,k3,k4,k1)
        - (A(3)+A(4))*zb(k1,l3)*zb(k1,l5)*za(k2,l4)*za(k2,l6)
        + A(5)*zba2(k1,k3,k4,k2)
          *(zb(l3,l5)*za(k2,l4)*za(l6,k2)/za(k1,k2)
           +zb(k1,l3)*zb(k1,l5)*za(l4,l6)/zb(k1,k2))
      ) / s34 / s56 / s12;

      Xmm(3-h3,3-h5) = zb(l3,l5)/(zb(k1,k2)*s12*s34*s56)*( // @coverage-probe
          (A(3)+A(1))*s12*za(k1,l6)*za(l4,k2)
        - (A(4)+A(1))*s12*za(k2,l6)*za(l4,k1)
        + A(5)*(za(k2,l4)*za(k2,l6)*zba2(k2,k3,k4,k1)
               -za(k1,l4)*za(k1,l6)*zba2(k1,k3,k4,k2))
      );
    }
  }
}

extern "C" {
  void LRcalc_wrapper(int k1, int k2, int k3, int k4, int k5, int k6,
                      std::complex<double>* fza, std::complex<double>* fzb,
                      std::complex<double>* fA,
                      std::complex<double>* fXpp, std::complex<double>* fXmp,
                      std::complex<double>* fXpm, std::complex<double>* fXmm) {
    using namespace mxpart_mod;
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    FArray1D<std::complex<double>> A(fA, 6);
    FArray2D<std::complex<double>> Xpp(fXpp, 2, 2);
    FArray2D<std::complex<double>> Xmp(fXmp, 2, 2);
    FArray2D<std::complex<double>> Xpm(fXpm, 2, 2);
    FArray2D<std::complex<double>> Xmm(fXmm, 2, 2);
    LRcalc(k1, k2, k3, k4, k5, k6, za, zb, A, Xpp, Xmp, Xpm, Xmm);
  }
